	EVENTS_SUBTITLE = "All of Midnight's world events: what's happening now and what's coming in the next day. Click a live event to set a route; hover for what it is and what it rewards.",
	EVENTS_NONE = "No world events visible right now — the scheduler may still be loading. Try again in a few seconds.",
	WORLD_SUBTITLE = "Midnight's weekly world content in Quel'Thalas. A Ritual Site is active in one zone and the Void assaults another — both share the Bazaar hub, Field Accolades and renown.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals combines Midnight's two rotating world systems. Ritual Sites: disrupt the active site (purple map icon) at its Curious Obelisk. Void Assaults: clear Void Strikes in the active zone to trigger a Void Incursion. Both award Field Accolades, fill your Great Vault World row and feed the shared Ritual Sites renown. Pick up both weeklies at the Bazaar hub in Silvermoon City.",
	TAB_REFERENCE = "Basics",
	REF_PANEL_INTRO = "Simple explanations for endgame systems. More topics will appear here over time.",
	REF_MORE_COMING = "More profession guides coming soon (blacksmithing, jewelcrafting, mining, cooking, fishing, and more).",
	INFO_DRAWER_BODY_REFERENCE = "Beginner-friendly guides: Dawncrests, where to spend them, and Warband bonuses. More topics (professions, etc.) will be added here.",
	TAB_SMC = "Silvermoon City",
