	TAB_TOOLBOX = "Toolbox",
	-- Patch 12.0.7 codex articles
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "A portal in the Voidstorm (Screaming Ridge) leads to one of two rotating Void worlds: fungal Naigtal or frozen Val. Each offers world quests, rares, zone events and a world boss (Nexus-Captain Leth'ir / Imperator Pertinax). The Showdown weekly awards a Riftstalker's Cache and counts toward the Great Vault World row. Optional Heroic World Tier raises difficulty and rewards — pick it at the portal. Start with Riftblade Maella in Silvermoon City.",
	CODEX_127_SPOREFALL_TITLE = "Sporefall Raid (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Single-boss raid in Harandar: Rotmire, a fungal giant. Same Season 1 tier with higher item levels (LFR 259 / Normal 272 / Heroic 285 / Mythic 298); Mythic is flexible with 15-25 players. Pick up a Delicious Sporesnack once per week on any difficulty — four in total buys the Luminous Sporeglider mount.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runes (12.0.7)",
	CODEX_127_FOLIO_BODY = "New power system that takes no gear slot. Unlock it via the Sunstrider Omnium questline with Magister Umbric and Grand Magister Rommath on Quel'Danas. Each week the 'Seeking Knowledge' quest grants a Mote of Omnial Inquiry to unlock one of five rune rows; runes swap freely out of combat.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (Jun 30 - Aug 11)",
	CODEX_127_TIMEWAYS_BODY = "Timewalking marathon featuring six Dragonflight dungeons. Run four dungeons in a week for that week's Mastery buff; earn Mastery in four separate weeks to claim the Spawn of Vyranoth mount.",
	CODEX_127_RITUALRENOWN_TITLE = "Ritual Sites Renown (12.0.7)",
	CODEX_127_RITUALRENOWN_BODY = "Ritual Sites have an account-wide renown track (8 ranks) in the Journeys window. Ranking up makes every site richer: healing Regeneration Orbs, then rare enemies (rank 4), buff shrines (rank 5), bigger treasures (rank 7) and rare elites (rank 8) — all dropping extra spoils. It also unlocks Silvermoon vendor goodies: void housing decor (rank 3, Rae'ana), pets (rank 6, Sergeant Vornin) and the Void-Touched Hawkstrider mount (rank 8, Sergeant Vornin). Every reward is Warband-wide, so your progress counts for the whole account. Click the glowing Loa Shrines inside a site for a 60-minute stat buff (e.g. +10% critical strike).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "Work in progress",
	TAB_BETA_TOOLTIP_BODY = "This tab is early beta — content is incomplete, may change often, and is not ready for full use yet.",
	TAB_ADDONS = "Addons",
	SEARCH_CHAT_TAB_ACADEMY = "Opened tab: Role Academy",

	ACADEMY_SUBTITLE = "Short masterclass for tanking and healing in groups - mindset, prep checkboxes, and a gentle ramp into dungeons. Not a parse guide.",
	ACADEMY_TRACK_TANK = "Tank track",
	ACADEMY_TRACK_HEAL = "Heal track",
	ACADEMY_LINK_MACROS = "Macros",
	ACADEMY_LINK_CONSUMABLES = "Consumables",
	ACADEMY_LINK_GUIDE = "Guides",
	ACADEMY_LINK_DELVES = "Delves",
	ACADEMY_LINK_CLASS = "My class",
	ACADEMY_CLASS_FMT = "Logged in: %s - %s (open Macros / Consumables / Guides from the sidebar)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Opened Macros for %s - %s. Also check Consumables for flasks and pots.",

	ACADEMY_PREF_TITLE = "Pre-flight checklist (tick when ready)",
	ACADEMY_PREF_HINT = "Ticks are saved in your settings. Open the matching tab from the sidebar when you prep.",
	ACADEMY_PREF_TANK_INTERRUPT = "Interrupt macro on my bar (Macros tab)",
	ACADEMY_PREF_TANK_DEFENSIVE = "One defensive ready (Guides -> Defensives or In groups tab)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flask / pot ready (Consumables tab)",
	ACADEMY_PREF_TANK_TAUNT = "I know my taunt key (dummy test once)",
	ACADEMY_PREF_HEAL_MACROS = "Mouseover / focus heal macros (Macros tab)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Personal defensive on bar (Guides -> Defensives or In groups)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Mana pot / flask (Consumables tab)",
	ACADEMY_PREF_HEAL_PRACTICE = "Practiced hover-heal on a friend once",

	ACADEMY_TANK_INTRO_TITLE = "Tank mindset",
	ACADEMY_TANK_INTRO_BODY = "Your job is to set pace and hold attention - not to top damage meters.\n\nOne steady pull beats a perfect rotation on a dead group. Say pulls out loud if it helps: \"pulling in 3\".",
	ACADEMY_TANK_PULL_TITLE = "During a pull (first 10 seconds)",
	ACADEMY_TANK_PULL_BODY = "1. Grab the pack (taunt / threat).\n2. Face enemies away from the group when you can.\n3. Use one defensive if damage spikes - save the second for \"oh no\".\n4. Interrupt the cast that hurts most (often heal or big hit).\n\nYou do not need every ability on cooldown immediately.",
	ACADEMY_TANK_WIPE_TITLE = "When it goes wrong",
	ACADEMY_TANK_WIPE_BODY = "A wipe is data, not a verdict. Ask: \"Was I too far ahead?\" or \"Did I save a defensive?\"\n\nRepair, eat, try again.",
	ACADEMY_TANK_DUNGEON_TITLE = "Your first dungeon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Start normal with friends or guildies if you can. Go slow on pulls - two small packs beat one huge chain.\n\nWatch the healer's mana; pause between pulls. It is OK to ask for CC or \"no big pull yet\".",
	ACADEMY_TANK_RAID_TITLE = "Raids and LFR (later)",
	ACADEMY_TANK_RAID_BODY = "LFR is the gentle raid intro: forgiving, many healers. Focus on boss taunt timings and standing still in the right place.\n\nMythic raid tanking is not the next step - comfort in heroic/LFR first.",
	ACADEMY_TANK_CHAT_TITLE = "Party chat",
	ACADEMY_CHAT_HINT = "Click a line or the copy icon, then Ctrl+C to paste in party chat.",
	ACADEMY_CHAT_COPY_TIP = "Select this line (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Still learning tank - go slow please.\"\n\"Pulling in 3...\"\n\"Need a breather for mana.\"\n\"Interrupt on [spell name] - I have it next.\"\n\"One more try - I know that pull now.\"",
	ACADEMY_TANK_LADDER_TITLE = "Anxiety ladder (recommended order)",
	ACADEMY_TANK_LADDER_BODY = "1. Open world elites with a friend\n2. Delves (smaller instance - Delves tab)\n3. Normal dungeon with people you trust\n4. Heroic / LFR when comfortable\n\nSkip a step until it feels boring, not terrifying.",
	ACADEMY_TANK_BOTH_TITLE = "Learning heal as well?",
	ACADEMY_TANK_BOTH_BODY = "Great - but pick one main role in dungeons for a while. Practice the other in delves or open world.\n\nSwitching tank and heal in the same M+ pug doubles stress; mastery in one role first builds confidence for the second.",

	ACADEMY_HEAL_INTRO_TITLE = "Heal mindset",
	ACADEMY_HEAL_INTRO_BODY = "You are not responsible for everyone at 100% health all the time.\n\nYour job is triage: keep the tank alive, save the person about to die, then the rest. Some damage is normal - panic overhealing empties mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (who first?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. You (if you're dying - dead healer heals nobody)\n2. Tank (if the pack is still on them)\n3. Anyone under ~40% or with a deadly debuff\n4. Everyone else with efficient heals\n\nBig heal after big damage; small heals between events.",
	ACADEMY_HEAL_WIPE_TITLE = "When it goes wrong",
	ACADEMY_HEAL_WIPE_BODY = "\"Could I have saved the tank?\" is the useful question - not \"why did DPS stand in fire?\"\n\nIf mana was empty, use more efficient spells next time. One wipe does not mean you cannot heal.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Your first dungeon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Tell the group you are learning. Stand in range of the tank; let DPS take a scratch before you blast mana.\n\nBetween pulls: drink, buff, breathe. You are allowed to say \"oom, 5 sec\".",
	ACADEMY_HEAL_RAID_TITLE = "Raids and LFR (later)",
	ACADEMY_HEAL_RAID_BODY = "LFR: raid-wide damage is predictable after one wipe. Learn the fight timer, not every player's bars.\n\nRaid heals use the same triage - tank and raid cooldown windows first.",
	ACADEMY_HEAL_CHAT_TITLE = "Party chat",
	ACADEMY_HEAL_CHAT_BODY = "\"Learning healer - I'll call low mana.\"\n\"Tank is priority - shout if you need a breather.\"\n\"Big heal on you - watch your health.\"\n\"Oom 5 sec between pulls.\"\n\"That was on me - I'll save more for the tank next pull.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Anxiety ladder (recommended order)",
	ACADEMY_HEAL_LADDER_BODY = "1. Heal a friend in open world\n2. Delves with a small group\n3. Normal dungeon with patient friends\n4. Raid LFR / heroic when ready\n\nDelves are the softest step into instanced content.",
	ACADEMY_HEAL_BOTH_TITLE = "Learning tank as well?",
	ACADEMY_HEAL_BOTH_BODY = "Use the Tank track for dungeon queueing; keep healing in delves until tanking feels familiar.\n\nTwo roles in one week in pugs is a lot - one role as \"main\" reduces fear.",

	INFO_DRAWER_BODY_ACADEMY = "Role Academy: tank/heal tracks, pre-flight checkboxes, dungeon vs raid notes, and party chat lines. Leveling Guides adds an In groups advisor tab per role. Use the sidebar for Macros, Consumables, Guides, and Delves.",
